package org.brightstats.desktop;
import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import javafx.stage.Window;
import org.brightstats.stats.*;

final class SegmentationDialog {
    record Settings(PredictionSegmentation.Options options,int[] initialAssignments,FiniteMixture.Options mixture){Settings{Objects.requireNonNull(options);initialAssignments=initialAssignments==null?null:initialAssignments.clone();}@Override public int[] initialAssignments(){return initialAssignments==null?null:initialAssignments.clone();}}
    private final Dialog<Settings> dialog=new Dialog<>();private final List<TextField> fields=new ArrayList<>();private Settings result;
    SegmentationDialog(Window owner,int rows,List<String> names,Settings previous){var o=previous==null?PredictionSegmentation.Options.defaults(rows):previous.options();dialog.initOwner(owner);dialog.setTitle("Prediction-oriented PLS segmentation");VBox body=new VBox(7);body.setPadding(new Insets(12));Label description=UiAppearance.label("Each candidate move refits group PLS models. R² is an in-sample optimization criterion; inspect class sizes, all starts, search limits and separate predictive validation. Pre-segmentation may reduce the objective.");description.setWrapText(true);body.getChildren().add(description);String[] labels={"Segments","Starts","Maximum iterations","Search depth (at most observation count)","Minimum segment size","Improvement tolerance","Base seed","Maximum group fits per start"};String[] values={""+o.segments(),""+o.repetitions(),""+o.maxIterations(),""+o.searchDepth(),""+o.minimumSize(),""+o.tolerance(),""+o.seed(),""+o.maximumGroupFits()};for(int i=0;i<labels.length;i++){var field=new TextField(values[i]);fields.add(field);body.getChildren().addAll(new Label(labels[i]),field);}ComboBox<PredictionSegmentation.Criterion> criterion=new ComboBox<>();criterion.getItems().setAll(PredictionSegmentation.Criterion.values());criterion.setValue(o.criterion());ComboBox<String> target=new ComboBox<>();target.getItems().setAll(names);target.getSelectionModel().select(o.target()>=0?o.target():names.size()-1);ComboBox<PredictionSegmentation.Initialization> initialization=new ComboBox<>();initialization.getItems().setAll(PredictionSegmentation.Initialization.values());initialization.setValue(o.initialization());CheckBox pre=new CheckBox("Perform an unguarded pre-segmentation round");pre.setSelected(o.preSegmentation());TextArea partition=new TextArea();partition.setPrefRowCount(3);if(previous!=null&&previous.initialAssignments()!=null)partition.setText(Arrays.toString(Arrays.stream(previous.initialAssignments()).map(value->value+1).toArray()).replaceAll("[\\[\\]]",""));Label mixLabel=UiAppearance.label("FIMIX initialization uses matching segment count and its separately configurable convergence/variance settings.");mixLabel.setWrapText(true);FiniteMixture.Options[] mixture={previous!=null&&previous.mixture()!=null?previous.mixture():FiniteMixture.Options.defaults()};Button configure=UiAppearance.button("Configure FIMIX starting model...");configure.setOnAction(event->MixtureDialog.show(owner,new MixtureDialog.Settings(mixture[0],false),rows).ifPresent(chosen->{if(!chosen.originalUnits())mixture[0]=chosen.mixture();else{Alert warning=new Alert(Alert.AlertType.WARNING,"POS uses standardized scores. Select standardized FIMIX initialization; the previous settings were retained.");warning.initOwner(owner);warning.showAndWait();}}));Label error=new Label();error.setWrapText(true);body.getChildren().addAll(UiAppearance.label("Objective"),criterion,UiAppearance.label("Target construct (target objectives only)"),target,UiAppearance.label("Starting partition"),initialization,pre,UiAppearance.label("Provided partition: one 1-based group number per prepared row"),partition,mixLabel,configure,error);ScrollPane scroll=new ScrollPane(body);scroll.setFitToWidth(true);scroll.setPrefSize(710,660);dialog.getDialogPane().setContent(scroll);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);dialog.setResizable(true);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{var chosen=new PredictionSegmentation.Options(Integer.parseInt(fields.get(0).getText().trim()),Integer.parseInt(fields.get(1).getText().trim()),Integer.parseInt(fields.get(2).getText().trim()),Integer.parseInt(fields.get(3).getText().trim()),Integer.parseInt(fields.get(4).getText().trim()),Double.parseDouble(fields.get(5).getText().trim()),Long.parseLong(fields.get(6).getText().trim()),pre.isSelected(),criterion.getValue(),target.getSelectionModel().getSelectedIndex(),initialization.getValue(),Integer.parseInt(fields.get(7).getText().trim()));if(chosen.searchDepth()>rows||(long)chosen.minimumSize()*chosen.segments()>rows)throw new IllegalArgumentException("Requested depth or segment sizes exceed available observations.");int[] assignments=null;if(chosen.initialization()==PredictionSegmentation.Initialization.PROVIDED){assignments=Arrays.stream(partition.getText().trim().split("[,\\s]+")).mapToInt(value->Integer.parseInt(value)-1).toArray();if(assignments.length!=rows)throw new IllegalArgumentException("Partition must contain one assignment for every prepared row.");int[] counts=new int[chosen.segments()];for(int label:assignments){if(label<0||label>=counts.length)throw new IllegalArgumentException("Partition group number is out of range.");counts[label]++;}for(int count:counts)if(count<chosen.minimumSize())throw new IllegalArgumentException("Provided group is below the minimum size.");}if(chosen.initialization()==PredictionSegmentation.Initialization.FIMIX&&mixture[0].segments()!=chosen.segments())throw new IllegalArgumentException("Configure FIMIX with the same segment count.");result=new Settings(chosen,assignments,mixture[0]);}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);}
    static Optional<Settings> show(Window owner,int rows,List<String> names,Settings previous){return new SegmentationDialog(owner,rows,names,previous).dialog.showAndWait();}
    static Settings smokeTest(Window owner,int rows,List<String> names){var test=new SegmentationDialog(owner,rows,names,null);test.dialog.show();test.fields.get(0).setText("0");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Zero POS groups accepted");test.fields.get(0).setText("2");test.fields.get(1).setText("1");test.fields.get(2).setText("200");test.fields.get(3).setText("0");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Zero POS depth accepted");test.fields.get(3).setText(""+rows);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null)throw new AssertionError("POS settings lost");return test.dialog.getResult();}
}
